import type { TestCase } from './cases.ts'
import { expect, expectEqual } from './cases.ts'

/**
 * Transaction edge cases. The function suite covers commit + rollback at
 * failed_index=1; these target shapes the function suite leaves alone:
 * empty / single-statement / mixed-read-write / failure-at-index-0.
 *
 * Each test creates its own scratch table to stay independent of `t`.
 */
export const TRANSACTION_EDGE_CASES: TestCase[] = [
  {
    name: 'transaction with empty statements array',
    async run({ driver, call }) {
      // Spec ambiguity: an empty txn is a no-op. Drivers commit an empty
      // transaction without error; the worker should pass that through.
      const r = await call('database::transaction', { db: driver, statements: [] })
      expectEqual(r.committed, true, 'empty transaction commits')
      expectEqual(Array.isArray(r.results) ? r.results.length : 0, 0, 'no results')
    },
  },
  {
    name: 'transaction with single statement',
    async run({ driver, dialect, call }) {
      const ph1 = dialect.placeholder(1)
      await call('database::execute', { db: driver, sql: 'DROP TABLE IF EXISTS tx_single' })
      await call('database::execute', {
        db: driver,
        sql: `CREATE TABLE tx_single (id ${dialect.idColumnDDL()}, n INT NOT NULL)`,
      })
      const r = await call('database::transaction', {
        db: driver,
        statements: [{ sql: `INSERT INTO tx_single (n) VALUES (${ph1})`, params: [7] }],
      })
      expectEqual(r.committed, true, 'committed=true for single-statement txn')
      const verify = await call('database::query', {
        db: driver,
        sql: 'SELECT n FROM tx_single',
      })
      expectEqual(Number(verify.rows[0].n), 7, 'row landed')
      await call('database::execute', { db: driver, sql: 'DROP TABLE tx_single' })
    },
  },
  {
    name: 'transaction read-your-writes (mixed INSERT/SELECT/INSERT)',
    async run({ driver, dialect, call }) {
      const ph1 = dialect.placeholder(1)
      await call('database::execute', { db: driver, sql: 'DROP TABLE IF EXISTS tx_ryw' })
      await call('database::execute', {
        db: driver,
        sql: `CREATE TABLE tx_ryw (id ${dialect.idColumnDDL()}, n INT NOT NULL)`,
      })
      const r = await call('database::transaction', {
        db: driver,
        statements: [
          { sql: `INSERT INTO tx_ryw (n) VALUES (${ph1})`, params: [100] },
          { sql: `SELECT n FROM tx_ryw`, params: [] },
          { sql: `INSERT INTO tx_ryw (n) VALUES (${ph1})`, params: [200] },
        ],
      })
      expectEqual(r.committed, true, 'committed=true for mixed txn')
      expect(Array.isArray(r.results), 'results is array')
      expectEqual(r.results.length, 3, 'three results')
      // Note: txn results carry rows positionally (Vec<Vec<Value>>) per
      // transaction.rs:64-67 — no column names. This differs from query/runStatement
      // which return column-keyed objects. The first SELECT row is `[100]`, not `{n: 100}`.
      const selectResult = r.results[1]
      expect(
        Array.isArray(selectResult.rows) && selectResult.rows.length === 1,
        `select sees exactly one row, got ${JSON.stringify(selectResult)}`,
      )
      const firstRow = selectResult.rows[0]
      expect(Array.isArray(firstRow), `row is positional array, got ${JSON.stringify(firstRow)}`)
      expectEqual(Number(firstRow[0]), 100, 'read-your-writes: select sees the just-inserted value')
      await call('database::execute', { db: driver, sql: 'DROP TABLE tx_ryw' })
    },
  },
  {
    name: 'transaction failure at index 0 reports failed_index=0',
    async run({ driver, dialect, call }) {
      const ph1 = dialect.placeholder(1)
      await call('database::execute', { db: driver, sql: 'DROP TABLE IF EXISTS tx_fail0' })
      await call('database::execute', {
        db: driver,
        sql: `CREATE TABLE tx_fail0 (id ${dialect.idColumnDDL()}, n INT NOT NULL)`,
      })
      // First statement violates NOT NULL; second never runs. failed_index must be 0.
      const r = await call('database::transaction', {
        db: driver,
        statements: [
          { sql: `INSERT INTO tx_fail0 (n) VALUES (${ph1})`, params: [null] },
          { sql: `INSERT INTO tx_fail0 (n) VALUES (${ph1})`, params: [99] },
        ],
      })
      expectEqual(r.committed, false, 'committed=false')
      expectEqual(r.failed_index, 0, 'failed_index=0')
      // Confirm rollback: zero rows.
      const verify = await call('database::query', {
        db: driver,
        sql: 'SELECT COUNT(*) AS c FROM tx_fail0',
      })
      expectEqual(Number(verify.rows[0].c), 0, 'rollback dropped all writes')
      await call('database::execute', { db: driver, sql: 'DROP TABLE tx_fail0' })
    },
  },
  {
    // Regression: the sqlite driver previously routed transaction steps via
    // brittle text matching (`starts_with("SELECT") || contains(" RETURNING ")`),
    // which mis-classified row-producing statements that begin with `WITH ...`
    // (CTE-prefixed SELECT) and `VALUES (...)`. Both were sent through
    // `c.execute()` which errors with ExecuteReturnedResults and aborted the
    // entire transaction. The driver now routes via the planner's
    // column_count(), which handles every statement shape correctly.
    //
    // Gated to sqlite_db: postgres/mysql tx paths use their own routing and
    // accept these statement shapes already. The bug was sqlite-specific.
    name: 'transaction handles CTE SELECT and VALUES (sqlite)',
    applies: ['sqlite_db'],
    async run({ driver, call }) {
      const r = await call('database::transaction', {
        db: driver,
        statements: [{ sql: 'WITH cte AS (SELECT 1 AS n) SELECT n FROM cte' }, { sql: 'VALUES (10), (20), (30)' }],
      })
      expectEqual(r.committed, true, 'CTE+VALUES tx committed')
      expect(Array.isArray(r.results) && r.results.length === 2, 'two step results')
      // CTE SELECT → 1 row
      expectEqual(r.results[0].rows.length, 1, 'CTE step row count')
      // VALUES → 3 rows
      expectEqual(r.results[1].rows.length, 3, 'VALUES step row count')
    },
  },
]

/**
 * In-memory mock for the subset of `database::*` that `DbStore` actually
 * uses: CREATE TABLE, SELECT (by-provider, list-all), UPSERT, DELETE.
 *
 * Tests that exercise the SQL-backed stores construct a `FakeDatabaseSdk`,
 * pass it into `new DbStore({ databaseName: 'test', ... }, fake)`, and get
 * deterministic round-trip behaviour without spawning a real iii-database
 * worker. The SQL parser is intentionally narrow -- it matches the exact
 * statements `database-store.ts` issues. If you change the statements,
 * update this helper.
 */

import type { ISdk, TriggerRequest } from 'iii-sdk';

type Row = { provider: string; payload: string; updated_at: number };

type DbTable = Map<string, Row>;

interface QueryResp {
  rows: Array<Record<string, unknown>>;
  row_count: number;
}

interface ExecuteResp {
  affected_rows: number;
  last_insert_id: string | null;
}

const RX_CREATE = /CREATE TABLE IF NOT EXISTS\s+(\w+)/i;
const RX_SELECT_ONE = /SELECT payload FROM\s+(\w+)\s+WHERE provider = \?/i;
const RX_SELECT_ALL = /SELECT provider, payload FROM\s+(\w+)/i;
const RX_INSERT_UPSERT = /INSERT INTO\s+(\w+)\s+\(provider, payload, updated_at\)/i;
const RX_DELETE = /DELETE FROM\s+(\w+)\s+WHERE provider = \?/i;

export class FakeDatabaseSdk {
  private readonly tables = new Map<string, DbTable>();
  /** Records every call routed through `trigger` for assertion in tests. */
  readonly calls: Array<{ function_id: string; payload: unknown }> = [];

  /** Mount as the `ISdk` a worker would use. */
  asSdk(): ISdk {
    // The full ISdk surface is large; tests only exercise `trigger`. Cast
    // through unknown so type-checking still catches signature drift on the
    // single method we implement.
    return { trigger: this.trigger } as unknown as ISdk;
  }

  /** Reset all tables (between tests). */
  reset(): void {
    this.tables.clear();
    this.calls.length = 0;
  }

  /** Inspect a table directly. */
  table(name: string): DbTable | undefined {
    return this.tables.get(name);
  }

  // Arrow so `asSdk().trigger(...)` keeps `this`.
  private trigger = async <_TPayload, TResp>(req: TriggerRequest<_TPayload>): Promise<TResp> => {
    this.calls.push({ function_id: req.function_id, payload: req.payload });
    if (req.function_id === 'database::query') {
      return this.handleQuery(req.payload) as TResp;
    }
    if (req.function_id === 'database::execute') {
      return this.handleExecute(req.payload) as TResp;
    }
    throw new Error(`FakeDatabaseSdk: unsupported function ${req.function_id}`);
  };

  private handleQuery(payload: unknown): QueryResp {
    const { sql, params } = parseSqlPayload(payload);
    let match = sql.match(RX_SELECT_ONE);
    if (match) {
      const tbl = this.tableOf(match[1] ?? '');
      const provider = String(params[0] ?? '');
      const row = tbl.get(provider);
      const rows = row ? [{ payload: row.payload }] : [];
      return { rows, row_count: rows.length };
    }
    match = sql.match(RX_SELECT_ALL);
    if (match) {
      const tbl = this.tableOf(match[1] ?? '');
      const rows = [...tbl.values()]
        .sort((a, b) => a.provider.localeCompare(b.provider))
        .map(({ provider, payload: p }) => ({ provider, payload: p }));
      return { rows, row_count: rows.length };
    }
    throw new Error(`FakeDatabaseSdk: unrecognised query SQL\n${sql}`);
  }

  private handleExecute(payload: unknown): ExecuteResp {
    const { sql, params } = parseSqlPayload(payload);
    let match = sql.match(RX_CREATE);
    if (match) {
      const name = match[1] ?? '';
      if (!this.tables.has(name)) this.tables.set(name, new Map());
      return { affected_rows: 0, last_insert_id: null };
    }
    match = sql.match(RX_INSERT_UPSERT);
    if (match) {
      const tbl = this.tableOf(match[1] ?? '');
      const provider = String(params[0] ?? '');
      const payloadStr = String(params[1] ?? '');
      const updatedAt = Number(params[2] ?? 0);
      tbl.set(provider, { provider, payload: payloadStr, updated_at: updatedAt });
      return { affected_rows: 1, last_insert_id: null };
    }
    match = sql.match(RX_DELETE);
    if (match) {
      const tbl = this.tableOf(match[1] ?? '');
      const provider = String(params[0] ?? '');
      const existed = tbl.delete(provider);
      return { affected_rows: existed ? 1 : 0, last_insert_id: null };
    }
    throw new Error(`FakeDatabaseSdk: unrecognised execute SQL\n${sql}`);
  }

  private tableOf(name: string): DbTable {
    let tbl = this.tables.get(name);
    if (!tbl) {
      tbl = new Map();
      this.tables.set(name, tbl);
    }
    return tbl;
  }
}

function parseSqlPayload(payload: unknown): { db: string; sql: string; params: unknown[] } {
  const p = (payload ?? {}) as { db?: unknown; sql?: unknown; params?: unknown };
  return {
    db: String(p.db ?? ''),
    sql: String(p.sql ?? ''),
    params: Array.isArray(p.params) ? p.params : [],
  };
}

//! Cross-cutting coercion tests — every JSON shape, both directions.

use database::value::{JsonParam, RowValue};
use serde_json::json;

#[test]
fn from_json_slice_happy_path() {
    // exercises the slice helper's happy path; the InvalidParam branch is hard
    // to trigger from JSON in serde_json 1.x and is left for direct unit testing.
    let values = vec![json!(1), json!("ok"), json!(null)];
    let out = JsonParam::from_json_slice(&values).unwrap();
    assert_eq!(out.len(), 3);
    assert_eq!(out[0], JsonParam::Int(1));
    assert_eq!(out[1], JsonParam::Text("ok".into()));
    assert_eq!(out[2], JsonParam::Null);
}

#[test]
fn row_value_round_trip_text() {
    assert_eq!(RowValue::Text("hi".into()).to_json(), json!("hi"));
}

#[test]
fn row_value_float_nan_becomes_null() {
    // serde_json::Number cannot represent NaN; we surface it as JSON null
    // rather than failing.
    let v = RowValue::Float(f64::NAN);
    assert_eq!(v.to_json(), json!(null));
}

import type { ISdk } from '../runtime/iii.js';
import { logger } from '../runtime/otel.js';
import type { ModelLimit } from './overflow.js';

export type ResolvedModel = {
  providerID: string;
  modelID: string;
  modelLimit: ModelLimit;
} | null;

export async function fetchModelLimit(
  iii: ISdk,
  providerID: string,
  modelID: string,
): Promise<ResolvedModel> {
  try {
    const entry = await iii.trigger<
      unknown,
      {
        id?: string;
        provider?: string;
        context_window?: number;
        max_output_tokens?: number;
      } | null
    >({
      function_id: 'models::get',
      payload: { provider: providerID, model_id: modelID },
      timeoutMs: 5_000,
    });

    if (!entry) {
      logger.debug('model-resolver: model not found in catalog', { providerID, modelID });
      return null;
    }

    const context = typeof entry.context_window === 'number' ? entry.context_window : 0;
    const output = typeof entry.max_output_tokens === 'number' ? entry.max_output_tokens : 0;

    return {
      providerID,
      modelID,
      modelLimit: { context, input: context, output },
    };
  } catch (err) {
    logger.debug('model-resolver: models::get failed', {
      providerID,
      modelID,
      err: String(err),
    });
    return null;
  }
}

export async function resolveModelFromSession(
  iii: ISdk,
  session_id: string,
): Promise<ResolvedModel> {
  try {
    const resp = await iii.trigger<
      unknown,
      { messages?: Array<{ entry_id?: string; message?: Record<string, unknown> }> }
    >({
      function_id: 'session-tree::messages',
      payload: { session_id },
      timeoutMs: 10_000,
    });

    const messages = resp?.messages ?? [];
    let providerID: string | null = null;
    let modelID: string | null = null;

    for (let i = messages.length - 1; i >= 0; i--) {
      const m = messages[i]?.message;
      if (!m || m.role !== 'assistant') continue;
      if (!providerID && typeof m.provider === 'string' && m.provider) providerID = m.provider;
      if (!modelID && typeof m.model === 'string' && m.model) modelID = m.model;
      if (providerID && modelID) break;
    }

    if (!providerID || !modelID) return null;

    return fetchModelLimit(iii, providerID, modelID);
  } catch (err) {
    logger.debug('model-resolver: session scan failed', { session_id, err: String(err) });
    return null;
  }
}

// Fallback when no assistant message carries provider/model yet (first-turn
// sessions, error-only sessions). The orchestrator writes run_request at
// agent::session/<sid>/run_request during run::start.
export async function resolveModelFromRunRequest(
  iii: ISdk,
  session_id: string,
): Promise<ResolvedModel> {
  try {
    const req = await iii.trigger<unknown, { provider?: string; model?: string } | null>({
      function_id: 'state::get',
      payload: { scope: 'agent', key: `session/${session_id}/run_request` },
      timeoutMs: 5_000,
    });
    const providerID = typeof req?.provider === 'string' && req.provider ? req.provider : null;
    const modelID = typeof req?.model === 'string' && req.model ? req.model : null;
    if (!providerID || !modelID) return null;
    return fetchModelLimit(iii, providerID, modelID);
  } catch (err) {
    logger.debug('model-resolver: run_request fetch failed', { session_id, err: String(err) });
    return null;
  }
}

//! Interactive-transaction registry.
//!
//! Holds `PinnedConn`s that are currently inside a server-side
//! `BEGIN ... COMMIT/ROLLBACK` block. Each entry pins one pool connection
//! under a UUID handle; `transactionQuery` / `transactionExecute` /
//! `commitTransaction` / `rollbackTransaction` look up the handle and
//! run SQL on the held connection.
//!
//! Timeouts are enforced by a background sweep task (`spawn_timeout_watcher`)
//! that polls every second and best-effort-rollbacks any entry whose
//! deadline has passed. The sweep takes the entry from the map *first*
//! (so concurrent handler calls fast-fail with `TRANSACTION_NOT_FOUND`),
//! then waits for any in-flight statement to release the per-conn mutex
//! before issuing `ROLLBACK` — graceful rather than ripping the connection
//! out mid-statement.

use crate::config::DriverKind;
use crate::driver;
use crate::error::DbError;
use crate::handle::PinnedConn;
use chrono::{DateTime, Duration as CDuration, Utc};
use iii_observability::Logger;
use schemars::JsonSchema;
use serde::Serialize;
use serde_json::json;
use std::collections::HashMap;
use std::sync::Arc;
use std::time::Duration;
use tokio::sync::{Mutex, OwnedMutexGuard, RwLock};
use uuid::Uuid;

/// JSON wire envelope returned by `beginTransaction`.
#[derive(Debug, Clone, Serialize, JsonSchema)]
pub struct TxHandleResponse {
    pub id: String,
    pub expires_at: DateTime<Utc>,
}

struct TxEntry {
    db_name: String,
    driver: DriverKind,
    started_at: DateTime<Utc>,
    deadline: DateTime<Utc>,
    conn: Arc<Mutex<PinnedConn>>,
}

/// Owned-guard return shape for `TxRegistry::lock`. The caller holds the
/// per-conn mutex via `guard` for the duration of one statement; the other
/// fields are pre-extracted metadata so handlers don't have to re-read the
/// map after locking.
pub struct TxLock {
    pub db_name: String,
    pub driver: DriverKind,
    pub started_at: DateTime<Utc>,
    pub guard: OwnedMutexGuard<PinnedConn>,
}

/// Return shape for `TxRegistry::take`. The caller has exclusive ownership
/// of the conn Arc; locking it and running COMMIT/ROLLBACK on the variant
/// is the caller's job.
pub struct TakenTx {
    pub db_name: String,
    pub driver: DriverKind,
    pub started_at: DateTime<Utc>,
    pub conn_arc: Arc<Mutex<PinnedConn>>,
}

/// Map of `transaction_id` (UUIDv4 string) → `TxEntry`. Cheap to clone
/// (single `Arc<RwLock<...>>`); store it in `AppState` directly.
#[derive(Clone, Default)]
pub struct TxRegistry {
    inner: Arc<RwLock<HashMap<String, TxEntry>>>,
}

impl TxRegistry {
    pub fn new() -> Self {
        Self::default()
    }

    /// Insert a freshly-begun transaction. The caller has already pulled a
    /// connection from the pool and issued `BEGIN [ISOLATION LEVEL X]` on
    /// it. We just record the pinned conn + metadata and return the handle.
    pub async fn insert(
        &self,
        db_name: String,
        driver: DriverKind,
        conn: PinnedConn,
        timeout: Duration,
    ) -> TxHandleResponse {
        let id = Uuid::new_v4().to_string();
        let now = Utc::now();
        // Clamp pathologically-large `timeout`s to `i64::MAX` ms so the
        // chrono arithmetic doesn't panic. The handler clamps to 5 minutes
        // long before this lands.
        let deadline =
            now + CDuration::from_std(timeout).unwrap_or_else(|_| CDuration::seconds(30));
        let entry = TxEntry {
            db_name,
            driver,
            started_at: now,
            deadline,
            conn: Arc::new(Mutex::new(conn)),
        };
        self.inner.write().await.insert(id.clone(), entry);
        TxHandleResponse {
            id,
            expires_at: deadline,
        }
    }

    /// Acquire an exclusive lock on the pinned conn for query/execute.
    /// Returns `TRANSACTION_NOT_FOUND` if the id is unknown, has been
    /// finalized, or has been auto-rolled-back by the timeout watcher.
    /// The returned `OwnedMutexGuard` queues behind any concurrent
    /// statement on the same id; callers serialize naturally.
    pub async fn lock(&self, id: &str) -> Result<TxLock, DbError> {
        // Extract the Arc under a brief read lock, then await `lock_owned`
        // outside the map's read lock. Holding the map read-lock across an
        // `.await` would block all other handler lookups (begin/lock/take)
        // for the duration of any in-flight statement on this id.
        let g = self.inner.read().await;
        let entry = g.get(id).ok_or_else(|| DbError::TransactionNotFound {
            transaction_id: id.to_string(),
        })?;
        let db_name = entry.db_name.clone();
        let driver = entry.driver;
        let started_at = entry.started_at;
        let arc = Arc::clone(&entry.conn);
        drop(g);
        let guard = arc.lock_owned().await;
        Ok(TxLock {
            db_name,
            driver,
            started_at,
            guard,
        })
    }

    /// Atomically remove an entry from the registry and return the conn
    /// Arc plus metadata. Subsequent `lock()` and `take()` calls against
    /// the id return `TRANSACTION_NOT_FOUND`. Used by `commitTransaction`
    /// and `rollbackTransaction` to finalize the txn.
    pub async fn take(&self, id: &str) -> Result<TakenTx, DbError> {
        let entry =
            self.inner
                .write()
                .await
                .remove(id)
                .ok_or_else(|| DbError::TransactionNotFound {
                    transaction_id: id.to_string(),
                })?;
        Ok(TakenTx {
            db_name: entry.db_name,
            driver: entry.driver,
            started_at: entry.started_at,
            conn_arc: entry.conn,
        })
    }

    /// Spawn the timeout watcher task. Polls every 1 s, rolls back any
    /// transaction whose deadline has passed, and removes the entry. The
    /// returned `JoinHandle` is owned by `main.rs` for the lifetime of the
    /// worker process; it loops forever until the runtime is dropped.
    pub fn spawn_timeout_watcher(&self, log: Logger) -> tokio::task::JoinHandle<()> {
        let me = self.clone();
        tokio::spawn(async move {
            let mut interval = tokio::time::interval(Duration::from_secs(1));
            // Drop ticks that fire while a previous sweep is still running.
            // A slow sweep (e.g. ROLLBACK of a long-running txn) would
            // otherwise queue up multiple back-to-back sweeps.
            interval.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Skip);
            loop {
                interval.tick().await;
                me.run_one_sweep(&log).await;
            }
        })
    }

    async fn run_one_sweep(&self, log: &Logger) {
        let now = Utc::now();
        // Take all expired entries in a single write-lock to keep the
        // critical section short; process them outside the lock.
        let expired: Vec<(String, TxEntry)> = {
            let mut g = self.inner.write().await;
            let ids: Vec<String> = g
                .iter()
                .filter(|(_, e)| e.deadline <= now)
                .map(|(id, _)| id.clone())
                .collect();
            ids.into_iter()
                .filter_map(|id| g.remove(&id).map(|e| (id, e)))
                .collect()
        };
        for (id, entry) in expired {
            let started_at = entry.started_at;
            let deadline = entry.deadline;
            let driver = entry.driver;
            let db_name = entry.db_name.clone();
            // Wait for any in-flight tx op to finish, then ROLLBACK.
            // The Arc's strong count is now 1 (we hold it; the map dropped
            // its ref), so dropping the guard at the end of the scope will
            // also drop the PinnedConn → conn returns to its pool.
            let mut guard = entry.conn.lock_owned().await;
            let result = rollback_inline(&mut guard).await;
            let now2 = Utc::now();
            let duration_ms = (now2 - started_at).num_milliseconds().max(0);
            let overshoot_ms = (now2 - deadline).num_milliseconds().max(0);
            match result {
                Ok(()) => log.warn(
                    "db_tx_timed_out",
                    Some(json!({
                        "db.system": driver_system(driver),
                        "db.name": db_name,
                        "db.transaction.id": id,
                        "duration_ms": duration_ms,
                        "deadline_overshoot_ms": overshoot_ms,
                    })),
                ),
                Err(e) => log.error(
                    "db_tx_timeout_rollback_failed",
                    Some(json!({
                        "db.system": driver_system(driver),
                        "db.name": db_name,
                        "db.transaction.id": id,
                        "duration_ms": duration_ms,
                        "error": serde_json::to_value(&e).ok(),
                    })),
                ),
            }
            drop(guard);
        }
    }

    /// Number of currently-tracked transactions. Test helper.
    #[cfg(test)]
    pub async fn len(&self) -> usize {
        self.inner.read().await.len()
    }

    /// Whether the registry currently tracks no transactions. Test helper.
    #[cfg(test)]
    pub async fn is_empty(&self) -> bool {
        self.inner.read().await.is_empty()
    }
}

/// Map `DriverKind` to the OTel `db.system` semantic-convention value.
pub fn driver_system(d: DriverKind) -> &'static str {
    match d {
        DriverKind::Postgres => "postgres",
        DriverKind::Mysql => "mysql",
        DriverKind::Sqlite => "sqlite",
    }
}

/// Dispatch `ROLLBACK` onto whatever driver variant the locked conn is.
/// Used by the timeout sweep; explicit `rollbackTransaction` calls invoke
/// the driver helpers directly in the handler.
async fn rollback_inline(guard: &mut OwnedMutexGuard<PinnedConn>) -> Result<(), DbError> {
    match &mut **guard {
        PinnedConn::Sqlite(slot) => driver::sqlite::tx_rollback(slot).await,
        PinnedConn::Postgres(client) => driver::postgres::tx_rollback(client).await,
        PinnedConn::Mysql(conn) => driver::mysql::tx_rollback(conn).await,
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::config::PoolConfig;
    use crate::pool::SqlitePool;

    async fn sqlite_pinned() -> PinnedConn {
        let pool = SqlitePool::new("sqlite::memory:", &PoolConfig::default()).unwrap();
        let conn = pool.acquire().await.unwrap();
        PinnedConn::Sqlite(Some(conn))
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn insert_then_lock_returns_metadata() {
        let reg = TxRegistry::new();
        let conn = sqlite_pinned().await;
        let h = reg
            .insert(
                "primary".into(),
                DriverKind::Sqlite,
                conn,
                Duration::from_secs(30),
            )
            .await;
        assert_eq!(h.id.len(), 36);
        let lock = reg.lock(&h.id).await.unwrap();
        assert_eq!(lock.db_name, "primary");
        assert!(matches!(lock.driver, DriverKind::Sqlite));
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn lock_after_take_returns_transaction_not_found() {
        // Once `take` removes an entry, subsequent `lock` lookups must
        // fast-fail with TRANSACTION_NOT_FOUND — this is what makes
        // commitTransaction/rollbackTransaction one-shot finalization.
        let reg = TxRegistry::new();
        let conn = sqlite_pinned().await;
        let h = reg
            .insert(
                "primary".into(),
                DriverKind::Sqlite,
                conn,
                Duration::from_secs(30),
            )
            .await;
        let _taken = reg.take(&h.id).await.unwrap();
        match reg.lock(&h.id).await {
            Err(DbError::TransactionNotFound { transaction_id }) => {
                assert_eq!(transaction_id, h.id);
            }
            Err(other) => panic!("expected TransactionNotFound, got {other:?}"),
            Ok(_) => panic!("expected TransactionNotFound, got Ok"),
        }
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn take_twice_returns_transaction_not_found() {
        let reg = TxRegistry::new();
        let conn = sqlite_pinned().await;
        let h = reg
            .insert(
                "primary".into(),
                DriverKind::Sqlite,
                conn,
                Duration::from_secs(30),
            )
            .await;
        let _first = reg.take(&h.id).await.unwrap();
        assert!(matches!(
            reg.take(&h.id).await,
            Err(DbError::TransactionNotFound { .. })
        ));
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn lock_unknown_id_returns_transaction_not_found() {
        // `TxLock` holds an `OwnedMutexGuard` which has no `Debug` impl, so
        // we can't use `unwrap_err()` directly — pattern-match the Result.
        let reg = TxRegistry::new();
        match reg.lock("00000000-0000-0000-0000-000000000000").await {
            Err(DbError::TransactionNotFound { .. }) => {}
            Err(other) => panic!("expected TransactionNotFound, got {other:?}"),
            Ok(_) => panic!("expected TransactionNotFound, got Ok"),
        }
    }

    /// Regression: after the deadline elapses, the watcher's next sweep
    /// must (a) remove the entry from the map and (b) issue `ROLLBACK` on
    /// the pinned conn. We drive the sweep manually instead of waiting for
    /// the 1 s poll interval so the test runs in milliseconds.
    #[tokio::test(flavor = "multi_thread")]
    async fn timeout_sweep_removes_expired_entries_and_rolls_back() {
        let reg = TxRegistry::new();
        let conn = sqlite_pinned().await;
        // Open a "real" txn on the conn so ROLLBACK has something to abort.
        // BEGIN must succeed on a freshly-acquired sqlite conn — no
        // ambient transaction state from the pool.
        let mut conn = conn;
        if let PinnedConn::Sqlite(slot) = &mut conn {
            driver::sqlite::tx_begin(slot, None).await.unwrap();
        }
        // Insert with a 1ms timeout, then wait past it.
        let h = reg
            .insert(
                "primary".into(),
                DriverKind::Sqlite,
                conn,
                Duration::from_millis(1),
            )
            .await;
        tokio::time::sleep(Duration::from_millis(20)).await;
        assert_eq!(reg.len().await, 1, "entry still present before sweep");

        let log = Logger::new();
        reg.run_one_sweep(&log).await;
        assert_eq!(reg.len().await, 0, "expired entry must be removed");

        // Subsequent lock fails with TRANSACTION_NOT_FOUND.
        match reg.lock(&h.id).await {
            Err(DbError::TransactionNotFound { .. }) => {}
            Err(other) => panic!("expected TransactionNotFound after sweep, got {other:?}"),
            Ok(_) => panic!("expected TransactionNotFound after sweep, got Ok"),
        }
    }

    /// Live entries (deadline still in the future) must not be touched.
    #[tokio::test(flavor = "multi_thread")]
    async fn timeout_sweep_leaves_live_entries_alone() {
        let reg = TxRegistry::new();
        let conn = sqlite_pinned().await;
        // 60-second deadline so a sub-second test can't possibly elapse it.
        let _h = reg
            .insert(
                "primary".into(),
                DriverKind::Sqlite,
                conn,
                Duration::from_secs(60),
            )
            .await;
        let log = Logger::new();
        reg.run_one_sweep(&log).await;
        assert_eq!(reg.len().await, 1, "live entry must survive sweep");
    }
}

/**
 * Drift-guard: the context-compaction worker writes flat session messages
 * to a key it composes itself in `flat-state.ts::flatMessagesKey`, because
 * importing `turn-orchestrator/state.ts::messagesKey` directly would
 * create a package-layer dependency (the orchestrator depends on
 * context-compaction via preflight). The two functions MUST agree forever
 * — otherwise compaction silently writes the rewritten history to a
 * shadow key the orchestrator never reads from.
 *
 * If this test fails, fix the key shape in flat-state.ts to match
 * messagesKey, then take a hard look at whether the duplication should
 * be lifted into a shared `runtime/keys.ts` module.
 */

